{
  "batch": 1,
  "condition": "witness_joint",
  "programs": [
    {
      "features": [],
      "name": "degree_first_bounded_reward",
      "rationale": "Keeps degree ordering primary, using bounded reward and conflict terms within each degree class. Requires no added graph computation, but cannot represent the certified nonlocal reversal.",
      "rule": "-degree + 0.4 * weight / (1 + weight + max_conflict_weight) - 0.1 * conflict_weight / ((1 + degree) * (1 + weight + conflict_weight))"
    },
    {
      "features": [],
      "name": "mean_conflict_density",
      "rationale": "Adjusts reward per blocked contact by a bounded comparison with mean conflicting reward, keeping count and weight scales separate. Uses only base inputs and remains blind to remote edge rearrangements.",
      "rule": "weight / (1 + degree) * (1 + 0.15 * (weight - conflict_weight / max(1, degree)) / (1 + weight + conflict_weight / max(1, degree)))"
    },
    {
      "features": [
        {
          "expression": {
            "op": "const",
            "value": 0
          },
          "name": "unused_placeholder"
        }
      ],
      "name": "tempered_neighbor_clustering",
      "rationale": "Uses only base density as a cost-aware candidate; no added feature is evaluated because the declared constant is unused. Its pointwise information cannot repair the witnessed reversal.",
      "rule": "weight / (1 + degree) * (1 + 0.08 * (weight - max_conflict_weight) / (1 + weight + max_conflict_weight))"
    },
    {
      "features": [
        {
          "expression": {
            "op": "const",
            "value": 0
          },
          "name": "unused_placeholder"
        }
      ],
      "name": "retained_peak_continuation",
      "rationale": "Uses compatible reward concentration through base aggregates as a cheap continuation approximation. The unused constant incurs no score-slice work, but this approximation cannot distinguish the remote witness.",
      "rule": "weight / (1 + degree) + 0.06 * weight * compatible_weight / ((1 + compatible_weight) * (1 + remaining_count))"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
