                                "op": "singleton"
                              }
                            ],
                            "op": "union"
                          }
                        ],
                        "op": "difference"
                      }
                    ],
                    "op": "sum_weights"
                  }
                ],
                "op": "add"
              }
            ],
            "op": "div"
          },
          "name": "retained_pack_fraction"
        }
      ],
      "name": "bounded_residual_packability",
      "rationale": "Modulates degree density by a bounded feasible packing fraction of the full root-compatible residual. It observes remote structure, but a global greedy pass and weight scan remain charged and may dominate runtime; witness repair is unverified.",
      "rule": "weight / (1 + degree) * (1 + 0.2 * min(1, max(0, retained_pack_fraction)))"
    },
