          },
          "name": "cover_displacement"
        }
      ],
      "name": "damped_cover_displacement",
      "rationale": "Uses root-conditioned cover displacement as a bounded correction to degree density. Global partitions can respond to remote arrangement changes, but heuristic cover differences can be unstable and two global cover computations may dominate the budget.",
      "rule": "weight / (1 + degree) * (1 + 0.12 * (weight - cover_displacement) / (1 + weight + abs(cover_displacement)))"
    },
