              }
            ],
            "op": "sub"
          },
          "name": "greedy_exchange"
        }
      ],
      "name": "crowding_scaled_greedy_exchange",
      "rationale": "Adds a normalized take-versus-skip greedy margin, with decision strength scaled by the fraction of active contacts blocked by the root. Reach is global; this scaling limits influence on large sparse sets but does not avoid either charged greedy computation.",
      "rule": "weight / (1 + degree) + 0.5 * weight * (1 + degree) / (1 + remaining_count) * greedy_exchange / (1 + weight + abs(greedy_exchange))"
    },
    {
      "features": [
        {
          "expression": {
