                    "op": "difference"
                  }
                ],
                "op": "clique_cover_weight"
              }
            ],
            "op": "sub"
          },
          "name": "completion_margin"
        }
      ],
      "name": "conservative_completion_gate",
      "rationale": "Compares a greedy root-included completion with a cover bound for excluding the root. A nonnegative margin relaxes crowding; otherwise a capped penalty retains density ranking. Both global operations remain charged regardless of the rule branch, and schedule benefit is unverified.",
      "rule": "weight / (1 + 0.5 * degree) if completion_margin >= 0 else weight / (1 + degree) * (1 + 0.1 * completion_margin / (1 + weight + abs(completion_margin)))"
    }
  ],
  "round": 2
